def cmp_semver(a, b):
    def parse(v):
        # Build metadata is ignored entirely
        main_part = v.split('+')[0]

        # Separate version from pre-release
        if '-' in main_part:
            version_str, pre_release_str = main_part.split('-', 1)
        else:
            version_str, pre_release_str = main_part, None

        # Parse major.minor.patch
        v_nums = [int(x) for x in version_str.split('.')]

        # Parse pre-release identifiers
        pre_ids = []
        if pre_release_str is not None:
            for id_str in pre_release_str.split('.'):
                if id_str.isdigit():
                    pre_ids.append(int(id_str))
                else:
                    pre_ids.append(id_str)
        return v_nums, pre_ids

    v1_nums, v1_pre = parse(a)
    v2_nums, v2_pre = parse(b)

    # Compare major, minor, patch numerically
    for n1, n2 in zip(v1_nums, v2_nums):
        if n1 > n2: return 1
        if n1 < n2: return -1

    # Pre-release precedence rules
    has_pre1 = v1_pre is not None
    has_pre2 = v2_pre is not None

    if has_pre1 and not has_pre2:
        return -1
    if not has_pre1 and has_pre2:
        return 1
    if not has_pre1 and not has_pre2:
        return 0

    # Both have pre-releases; compare identifiers left to right
    for i in range(min(len(v1_pre), len(v2_pre))):
        id1 = v1_pre[i]
        id2 = v2_pre[i]

        is_id1_num = isinstance(id1, int)
        is_id2_num = isinstance(id2, int)

        # Numeric identifiers sort before alphanumeric ones
        if is_id1_num and not is_id2_num:
            return -1
        if not is_id1_num and is_id2_num:
            return 1

        # If types are the same, compare values
        if id1 != id2:
            return 1 if id1 > id2 else -1

    # A longer identifier list wins if all preceding are equal
    if len(v1_pre) > len(v2_pre):
        return 1
    if len(v1_pre) < len(v2_pre):
        return -1

    return 0
