def parse_range(header, size):
    if not header or not header.startswith("bytes="):
        return None

    try:
        content = header[6:]
        if not content.strip():
            return None

        parts = content.split(",")
        results = []

        for p in parts:
            p = p.strip()
            if not p:
                continue

            start, end = -1, -1

            if p.startswith("-"):
                # Suffix range: -500
                val = int(p[1:])
                start = max(0, size - val)
                end = size - 1
            elif "-" in p:
                # Range range: 0-499 or 500-
                s_str, e_str = p.split("-", 1)
                start = int(s_str) if s_str else 0
                end = int(e_str) if e_str else size - 1
            else:
                # Single point: 0
                start = int(p)
                end = size - 1

            # A range whose start is at or past size is unsatisfiable
            if start >= size:
                continue

            # Clamp end to the last byte of the resource
            if end >= size:
                end = size - 1

            # A range is only valid if start <= end
            if start <= end:
                results.append((start, end))

        return results if results else None

    except (ValueError, IndexError):
        return None
