from datetime import datetime, timedelta

def next_fire(expr, after):
    def parse_field(field_str, min_val, max_val):
        is_star = (field_str == '*')
        parts = field_str.split(',')
        allowed = set()
        for part in parts:
            if not part:
                raise ValueError("Malformed expression: empty field part")
            if '/' in part:
                left, step_str = part.split('/')
                if not left or not step_str:
                    raise ValueError("Malformed expression: invalid slash usage")
                try:
                    step = int(step_str)
                except ValueError:
                    raise ValueError("Malformed expression: non-integer step")
                if step <= 0:
                    raise ValueError("Malformed expression: step must be positive")

                if left == '*':
                    low, high = min_val, max_val
                elif '-' in left:
                    try:
                        l_start, l_end = left.split('-')
                        low, high = int(l_start), int(l_end)
                        if low > high:
                            raise ValueError("Malformed expression: range start > end")
                    except ValueError:
                        raise ValueError("Malformed expression: invalid range")
                else:
                    try:
                        low = high = int(left)
                    except ValueError:
                        raise ValueError("Malformed expression: non-integer value")

                for i in range(low, high + 1, step):
                    allowed.add(i)
            else:
                if '-' in part:
                    try:
                        l_start, l_end = part.split('-')
                        low, high = int(l_start), int(l_end)
                        if low > high:
                            raise ValueError("Malformed expression: range start > end")
                        allowed.update(range(low, high + 1))
                    except ValueError:
                        raise ValueError("Malformed expression: invalid range")
                else:
                    try:
                        allowed.add(int(part))
                    except ValueError:
                        raise ValueError("Malformed expression: non-integer value")

        for val in allowed:
            if val < min_val or val > max_val:
                raise ValueError("Malformed expression: value out of bounds")
        return allowed, is_star

    fields = expr.split(' ')
    if len(fields) != 5:
        raise ValueError("Malformed expression: must have 5 fields")

    rules = {}
    bounds = [
        (0, 59),   # minute
        (0, 23),   # hour
        (1, 31),   # day-of-month
        (1, 12),   # month
        (0, 6)     # day-of-week
    ]

    keys = ['min', 'hour', 'dom', 'month', 'dow']
    for i in range(5):
        allowed, is_star = parse_field(fields[i], bounds[i][0], bounds[i][1])
        rules[keys[i]] = (allowed, is_star)

    def is_match(dt):
        if dt.minute not in rules['min'][0]: return False
        if dt.hour not in rules['hour'][0]: return False
        if dt.month not in rules['month'][0]: return False

        m_dom = rules['dom']
        m_dow = rules['dow']

        dom_star = m_dom[1]
        dow_star = m_dow[1]

        # Day-of-week mapping: 0=Sunday, 1=Monday, ..., 6=Saturday
        # dt.weekday() is 0=Monday, 6=Sunday.
        # (dt.weekday() + 1) % 7 maps Monday->1, ..., Saturday->6, Sunday->0.
        current_dow = (dt.weekday() + 1) % 7

        if not dom_star and not dow_star:
            return dt.day in m_dom[0] or current_dow in m_dow[0]
        elif not dom_star:
            return dt.day in m_dom[0]
        elif not dow_star:
            return current_dow in m_dow[0]
        else:
            return True

    curr = after
    while True:
        curr += timedelta(minutes=1)
        curr = curr.replace(second=0, microsecond=0)
        if is_match(curr):
            return curr
