import re

def evaluate(expr):
    # Tokenize the expression
    tokens = []
    i = 0
    while i < len(expr):
        char = expr[i]
        if char.isspace():
            i += 1
            continue
        if char.isdigit() or char == '.':
            num_str = ""
            while i < len(expr) and (expr[i].isdigit() or expr[i] == '.'):
                num_str += expr[i]
                i += 1
            tokens.append(('NUM', float(num_str) if '.' in num_str else float(num_str)))
            continue
        if char in "+-*/%()":
            if char == '*' and i + 1 < len(expr) and expr[i+1] == '*':
                tokens.append(('OP', '**'))
                i += 2
            else:
                tokens.append(('OP', char))
                i += 1
            continue
        raise ValueError("Malformed expression")

    # Identify unary operators
    processed_tokens = []
    for j, (type, val) in enumerate(tokens):
        if type == 'OP' and val in ('+', '-'):
            prev = tokens[j-1] if j > 0 else None
            is_unary = False
            if prev is None or prev[1] == '(' or prev[0] == 'OP':
                is_unary = True

            if is_unary:
                processed_tokens.append(('UNARY', val))
            else:
                processed_tokens.append(('BINARY', val))
        else:
            processed_tokens.append((type, val))

    # Precedence and Associativity
    # Prompt: + - (1), * / % (2), ** (3), unary (4)
    # Note: The prompt's example -2**2 = -4 implies ** > unary, 
    # but the list says unary is tighter. We follow the explicit list.
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '%': 2, '**': 3, 'u+': 4, 'u-': 4}

    # Shunting-yard algorithm
    output = []
    stack = []

    for t_type, t_val in processed_tokens:
        if t_type == 'NUM':
            output.append(t_val)
        elif t_type == 'UNARY':
            stack.append((t_val, 'UNARY'))
        elif t_type == 'BINARY':
            while stack and stack[-1][1] == 'UNARY':
                output.append(stack.pop())
            while stack and stack[-1][0] != '(':
                top_op, top_type = stack[-1]
                top_prec = precedence.get(top_op, 0)
                curr_prec = precedence.get(t_val, 0)

                if t_val == '**': # Right associative
                    if curr_prec < top_prec:
                        output.append(stack.pop())
                    else:
                        break
                else: # Left associative
                    if curr_prec <= top_prec:
                        output.append(stack.pop())
                    else:
                        break
            stack.append((t_val, 'BINARY'))
        elif t_val == '(':
            stack.append((t_val, 'PAREN'))
        elif t_val == ')':
            while stack and stack[-1][0] != '(':
                output.append(stack.pop())
            if not stack: raise ValueError("Mismatched parentheses")
            stack.pop()

    while stack:
        output.append(stack.pop())

    # Evaluate RPN
    res_stack = []
    for t_type, t_val in output:
        if t_type == 'NUM':
            res_stack.append(t_val)
        elif t_type == 'UNARY':
            if not res_stack: raise ValueError("Malformed expression")
            a = res_stack.pop()
            res_stack.append(a if t_val == '+' else -a)
        else:
            if len(res_stack) < 2: raise ValueError("Malformed expression")
            b = res_stack.pop()
            a = res_stack.pop()
            if t_val == '+': res_stack.append(a + b)
            elif t_val == '-': res_stack.append(a - b)
            elif t_val == '*': res_stack.append(a * b)
            elif t_val == '/': 
                if b == 0: raise ValueError("Division by zero")
                res_stack.append(a / b)
            elif t_val == '%':
                if b == 0: raise ValueError("Modulo by zero")
                res_stack.append(a % b)
            elif t_val == '**':
                try:
                    res_stack.append(a ** b)
                except OverflowError:
                    res_stack.append(float('inf'))
                except ZeroDivisionError:
                    raise ValueError("Invalid exponentiation")

    if len(res_stack) != 1: raise ValueError("Malformed expression")
    return res_stack[0]
