class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []
        self.num_components = n

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        root_a = self.find(a)
        root_b = self.find(b)

        if root_a != root_b:
            if self.size[root_a] < self.size[root_b]:
                # Attach smaller tree (root_a) to larger tree (root_b)
                self.parent[root_a] = root_b
                self.size[root_b] += self.size[root_a]
                self.history.append((root_a, root_b))
            else:
                # Attach smaller tree (root_b) to larger tree (root_a)
                self.parent[root_b] = root_a
                self.size[root_a] += self.size[root_b]
                self.history.append((root_b, root_a))

            self.num_components -= 1
            return True
        return False

