def to_base(n, alphabet):
    if n == 0:
        return alphabet[0]

    is_negative = n < 0
    n = abs(n)
    base = len(alphabet)
    digits = []

    while n > 0:
        digits.append(alphabet[n % base])
        n //= base

    res = "".join(reversed(digits))
    return "-" + res if is_negative else res

def from_base(s, alphabet):
    if not s:
        raise ValueError("Empty string")

    is_negative = False
    if s.startswith('-'):
        is_negative = True
        s = s[1:]
        if not s:
            raise ValueError("Invalid format")

    base = len(alphabet)
    char_map = {char: i for i, char in enumerate(alphabet)}
    res = 0

    for char in s:
        if char not in char_map:
            raise ValueError(f"Character '{char}' not in alphabet")
        res = res * base + char_map[char]

    return -res if is_negative else res
