import heapq

def topo_lex(graph):
    # Identify all unique nodes in the graph
    nodes = set(graph.keys())
    for neighbors in graph.values():
        nodes.update(neighbors)

    # Calculate in-degrees for all nodes
    in_degree = {node: 0 for node in nodes}
    for u, neighbors in graph.items():
        for v in neighbors:
            in_degree[v] += 1

    # Initialize min-heap with all nodes having in-degree 0
    # Using a heap ensures we always pick the lexicographically smallest available node
    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)

        # Check if current node has outgoing edges
        if u in graph:
            for v in graph[u]:
                in_degree[v] -= 1
                # If in-degree becomes 0, it's ready to be processed
                if in_degree[v] == 0:
                    heapq.heappush(heap, v)

    # If the result contains all nodes, no cycle exists
    if len(result) == len(nodes):
        return result
    else:
        return None
