        res = first_val
        for i in range(len(data['ops'])):
            next_val = eval_block(data['blocks'][i+1])
            if data['ops'][i] == '+':
                res += next_val
            else:
                res -= next_val
        return res

    def _is_reachable(self, start, target):
        if start == target:
            return True
        visited = set()
        stack = [start]
        while stack:
            curr = stack.pop()
            if curr == target:
                return True
            if curr not in visited:
                visited.add(curr)
                stack.extend(self.dependencies.get(curr, []))
        return False

    def set(self, cell, value):
