class Emitter {
  constructor() {
    this._events = {};
  }

  on(event, fn) {
    if (!this._events[event]) {
      this._events[event] = [];
    }
    const entry = { fn, once: false };
    this._events[event].push(entry);
    return () => this.off(event, fn);
  }

  once(event, fn) {
    if (!this._events[event]) {
      this._events[event] = [];
    }
    this._events[event].push({ fn, once: true });
  }

  off(event, fn) {
    const list = this._events[event];
    if (!list) return;
    const index = list.findIndex((entry) => entry.fn === fn);
    if (index !== -1) {
      list.splice(index, 1);
    }
  }

  emit(event, ...args) {
    const list = this._events[event];
    if (!list) return 0;

    const toRun = [...list];
    let count = 0;
    let firstError = null;

    for (const entry of toRun) {
      const currentIndex = list.findIndex((item) => item === entry);

      // If the listener was removed during the emit, skip it
      if (currentIndex === -1) continue;

      // Remove once listeners before they run
      if (entry.once) {
        list.splice(currentIndex, 1);
      }

      try {
        entry.fn(...args);
        count++;
      } catch (err) {
        if (!firstError) {
          firstError = err;
        }
      }
    }

    if (firstError) {
      throw firstError;
    }

    return count;
  }
}

module.exports = Emitter;
