    if (i < values.length) {
      const v = values[i];

      if (Array.isArray(v)) {
        const placeholders = v.map((_, idx) => `$${count + idx}`).join(", ");
        text += `(${placeholders})`;
        valuesList.push(...v);
        count += v.length;
      } else if (v && typeof v === "object" && "text" in v && "values" in v) {
        const offset = count - 1;
        const nestedText = v.text.replace(/\$(\d+)/g, (_, num) => {
