async function* chunkAsync(source, size) {
  const iterator = source[Symbol.asyncIterator] || source[Symbol.iterator];
  if (!iterator) {
    throw new TypeError('Source is not iterable');
  }

  let finishedNaturally = false;
  try {
    while (true) {
      const chunk = [];
      let done = false;

      for (let i = 0; i < size; i++) {
        const { value, done: isDone } = await iterator.next();
        if (isDone) {
          done = true;
          break;
        }
        chunk.push(value);
      }

      if (chunk.length > 0) {
        yield chunk;
      }

      if (done) {
        finishedNaturally = true;
        break;
      }
    }
  } finally {
    if (!finishedNaturally && typeof iterator.return === 'function') {
      await iterator.return();
    }
  }
}

module.exports = chunkAsync;
