function* zipLongest(fill, ...iterables) {
  if (iterables.length === 0) return;

  const iterators = iterables.map((it) => {
    if (typeof it[Symbol.iterator] === 'function') {
      return it[Symbol.iterator]();
    }
    return (function* () { yield it; })();
  });

  const activeIndices = new Set(iterators.map((_, i) => i));

  while (activeIndices.size > 0) {
    const row = [];
    for (let i = 0; i < iterators.length; i++) {
      if (activeIndices.has(i)) {
        const { value, done } = iterators[i].next();
        if (done) {
          activeIndices.delete(i);
          row.push(fill);
        } else {
          row.push(value);
        }
      } else {
        row.push(fill);
      }
    }

    if (activeIndices.size > 0) {
      yield row;
    }
  }
}

module.exports = zipLongest;
