const createStore = (reducer, initial) => {
  let state = initial;
  let listeners = new Set();
  let isDispatching = false;
  let isInsideSubscriberCount = 0;

  const getState = () => state;

  const dispatch = (action) => {
    if (isDispatching && isInsideSubscriberCount === 0) {
      throw new Error('Dispatching from inside a reducer is forbidden');
    }

    isDispatching = true;
    try {
      const nextState = reducer(state, action);
      state = nextState;

      const snapshot = Array.from(listeners);
      for (const fn of snapshot) {
        if (listeners.has(fn)) {
          isInsideSubscriberCount++;
          try {
            fn();
          } finally {
            isInsideSubscriberCount--;
          }
        }
      }
    } finally {
      isDispatching = false;
    }
  };

  const subscribe = (fn) => {
    listeners.add(fn);
    return () => {
      listeners.delete(fn);
    };
  };

  return {
    getState,
    dispatch,
    subscribe
  };
};

module.exports = createStore;
