async function toposortTasks(tasks) {
  const results = {};
  const promises = {};
  let firstError = null;

  const taskNames = Object.keys(tasks);

  // Validate existence of all dependencies
  for (const name of taskNames) {
    for (const dep of tasks[name].deps) {
      if (!(dep in tasks)) {
        throw new Error(`Missing dependency: ${dep}`);
      }
    }
  }

  // Cycle detection using DFS
  const visited = new Set();
  const visiting = new Set();
  const checkCycle = (name) => {
    if (visiting.has(name)) {
      throw new Error("Dependency cycle detected");
    }
    if (visited.has(name)) return;

    visiting.add(name);
    for (const dep of tasks[name].deps) {
      checkCycle(dep);
    }
    visiting.delete(name);
    visited.add(name);
  };

  for (const name of taskNames) {
    checkCycle(name);
  }

  /**
   * Recursively retrieves or creates a promise for a task.
   * Ensures that independent tasks run concurrently.
   */
  const getPromise = (name) => {
    if (promises[name]) return promises[name];

    promises[name] = (async () => {
      try {
        const task = tasks[name];
        const depValues = {};

        // Wait for all dependencies to resolve
        for (const dep of task.deps) {
          depValues[dep] = await getPromise(dep);
        }

        // Execute the task
        results[name] = await task.run(depValues);
      } catch (err) {
        // Capture the first error encountered in the execution tree
        if (!firstError) firstError = err;
        throw err;
      }
    })();

    return promises[name];
  };

  try {
    // Trigger all tasks. Promise.all will handle the concurrent execution.
    await Promise.all(taskNames.map((name) => getPromise(name)));
    return results;
  } catch (err) {
    // Ensure we throw the first error that occurred during execution
    if (firstError) throw firstError;
    throw err;
  }
}

module.exports = toposortTasks;
