type EmitArgs<E extends Record<string, unknown>, K extends keyof E> =
  E[K] extends void ? [K] : [K, E[K]];

export class Bus<E extends Record<string, unknown>> {
  private handlers = new Map<keyof E, Array<(payload: any) => void>>();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    let list = this.handlers.get(k);
    if (!list) {
      list = [];
      this.handlers.set(k, list);
    }
    list.push(fn);
    return () => {
      const current = this.handlers.get(k);
      if (current) {
        const index = current.indexOf(fn);
        if (index !== -1) current.splice(index, 1);
      }
    };
  }

  emit<K extends keyof E>(...args: EmitArgs<E, K>): void;
  emit<K extends keyof E>(...args: any[]): void {
    const [k, payload] = args;
    const handlers = this.handlers.get(k);
    if (handlers) {
      handlers.forEach((handler) => handler(payload));
    }
  }
}
