export type Result<T, E> =
  | { readonly _tag: 'ok'; readonly value: T }
  | { readonly _tag: 'err'; readonly error: E };

export const ok = <T, E>(value: T): Result<T, E> => ({ _tag: 'ok', value });
export const err = <T, E>(error: E): Result<T, E> => ({ _tag: 'err', error });

export function isOk<T, E>(r: Result<T, E>): r is Extract<Result<T, E>, { _tag: 'ok' }> {
  return r._tag === 'ok';
}

export function isErr<T, E>(r: Result<T, E>): r is Extract<Result<T, E>, { _tag: 'err' }> {
  return r._tag === 'err';
}

export function map<T, E, U>(r: Result<T, E>, f: (v: T) => U): Result<U, E> {
  if (isOk(r)) {
    return ok(f(r.value));
  }
  return err(r.error);
}

export function unwrapOr<T, E>(r: Result<T, E>, defaultValue: T): T {
  if (isOk(r)) {
    return r.value;
  }
  return defaultValue;
}
